 async function load(more=false){if(!more){reportOrders.clear();reportRecords.clear();updateReport();}const current=++serial;loading.hidden=false;$('#orders').setAttribute('aria-busy','true');$('#refresh').disabled=true;$('#found').textContent='Henter registreringer…';try{const query=$('#query').value.trim(),page=await rpc('list',{query,carrierCode,unbookedOnly,offset:more?next:0,recent:!more&&!query});if(current!==serial)return;if(!more)officeLive.accept(page.pulse);else officeLive.apply(page.pulse);if(!more){officeLive.clear();$('#orders').replaceChildren();shown=0;}else $('#orders .empty')?.remove();page.items.forEach(r=>{const key=r.delivery?.deliveryDate||'missing';let section=$('#orders').querySelector('[data-day="'+key+'"]');if(!section){section=document.createElement('section');section.dataset.day=key;section.className='packing-day';const title=document.createElement('h2');title.className='packing-date';title.textContent=key==='missing'?'Leveringsdag mangler':'Levering '+new Date(key+'T12:00:00Z').toLocaleDateString('da-DK',{day:'2-digit',month:'long',year:'numeric'});section.append(title);$('#orders').append(section);}section.append(reportCard(r));});shown+=page.items.length;$('#resultsTitle').textContent=query?'Søgeresultat · '+query:unbookedOnly?'Ikke-bookede ordrer efter leveringsdag':'Alle ordrer efter leveringsdag';$('#found').textContent=shown+' af '+page.total+' '+(page.total===1?'registrering':'registreringer');if(!page.items.length&&!more)$('#orders').innerHTML='<p class="card empty">'+(unbookedOnly?'Ingen ikke-bookede ordrer i perioden. Brug søgning, Vis flere eller Vis også bookede.':'Ingen registreringer i perioden. Brug søgning eller Vis flere.')+'</p>';next=page.next;$('#more').hidden=next===null;$('#message').textContent='';}catch(e){if(current!==serial)return;error(e.message);$('#found').textContent='Kunne ikke hente registreringer.';}finally{if(current===serial){$('#refresh').disabled=false;loading.hidden=true;$('#orders').setAttribute('aria-busy','false');}}}
