function orderCard(r,historic=false){
 const card=document.createElement('article');card.className='order card';
 const measurements=p=>[p.length,p.width,p.height].every(v=>v===null||v==='')?'Mål ikke angivet':[p.length,p.width,p.height].map(v=>v===null||v===''?'–':number(v)).join(' × ')+' cm';
 const weight=p=>p.weight===null||p.weight===''?'Vægt ikke angivet':number(p.weight)+' kg';
 card.innerHTML='<details class="order-fold"><summary class="order-summary"><div class="order-identity"><h2>'+(r.carrier?'<span class="carrier-badge" title="'+esc(r.carrier.label)+'">'+esc(r.carrier.code)+'</span> ':'')+((r.orders?.length||1)>1?'🔗 ':'Ordre ')+esc((r.orders||[r.order]).join(' + '))+(!historic&&window.OfficeLive?.isNew(r)?' <span class="new-order-badge" title="Pakket inden for de seneste 24 timer">Ny</span>':'')+'</h2>'+(r.delivery?'<p class="delivery-summary">'+esc(window.PackingData.address(r.delivery))+'</p>':'')+'<span class="muted">'+date(r.updatedAt)+((r.orders?.length||1)>1?' · '+r.orders.length+' ordrer · fælles pakning':'')+' · Pakket af '+esc(r.packedBy)+'</span></div><div class="summary-parcels">'+(r.carrier?.simple?[]:r.parcels).map((p,i)=>'<div><strong>Colli '+(i+1)+'</strong><span>'+measurements(p)+' · '+weight(p)+'</span></div>').join('')+'</div><div class="summary-total"><span class="pill">'+r.parcels.length+' colli</span><span>'+(r.carrier?.simple?'':totals(r.parcels))+'</span></div><span class="order-chevron" aria-hidden="true">⌄</span></summary><div class="order-body"><aside class="order-info"><dl>'+(r.delivery?'<dt>Leveringsadresse</dt><dd class="delivery-address">'+esc(r.delivery.address||r.delivery.customer)+'</dd>':'')+'<dt>Pakket / opdateret</dt><dd>'+date(r.updatedAt)+'</dd><dt>Pakket af</dt><dd>'+esc(r.packedBy)+'</dd><dt>Forsendelse</dt><dd>'+r.shipment+'</dd>'+(r.revision>1?'<dt>Senest opdateret af</dt><dd>'+esc(r.updatedBy)+'</dd>':'')+'</dl><button class="copy">Kopiér fragtinfo</button></aside><section class="order-images"><div class="row"><h3>Billeder</h3><span class="muted">'+r.photos.length+' '+(r.photos.length===1?'billede':'billeder')+'</span></div><div class="image-actions">'+(r.photos.length?'<button class="select-images primary" aria-pressed="false">Vælg</button><button class="download-selected" hidden disabled>Download valgte</button><span class="selection-count" role="status"></span><button class="load-images">Hent billeder</button>':'')+'</div><div class="photos office-photos"></div></section></div>'+(r.revision>1&&!historic?'<details class="order-history"><summary>Historik · '+r.revision+' versioner</summary><div class="history"></div></details>':'')+'</details>';
 card.querySelector('.copy').onclick=async e=>{const button=e.currentTarget;await copy(freight(r));button.textContent='Kopieret';setTimeout(()=>button.textContent='Kopiér fragtinfo',2000);};
 const photos=card.querySelector('.photos'),urls=new Array(r.photos.length),files=new Array(r.photos.length),selected=new Set();let selecting=false,loading=false;
 const select=card.querySelector('.select-images'),download=card.querySelector('.download-selected'),count=card.querySelector('.selection-count'),button=card.querySelector('.load-images');
 function updateSelection(){if(!select)return;select.textContent=selecting?'Annullér valg':'Vælg';select.setAttribute('aria-pressed',String(selecting));download.hidden=!selecting;download.disabled=!selected.size;count.textContent=selecting?selected.size+' valgt':'';photos.querySelectorAll('.photo-select').forEach(el=>el.hidden=!selecting);}
 if(select)select.onclick=()=>{selecting=!selecting;if(!selecting){selected.clear();photos.querySelectorAll('input').forEach(el=>el.checked=false);}updateSelection();};
 if(download)download.onclick=()=>{const chosen=[...selected].sort((a,b)=>a-b).map(i=>files[i]).filter(Boolean);if(chosen.length)downloadPhotoZip(chosen,'Ordre-'+String(r.order).replace(/[^a-zA-Z0-9_-]/g,'_')+'-billeder.zip');};
 r.photos.forEach((p,i)=>{const el=document.createElement('figure');el.innerHTML='<div class="photo-placeholder">'+(p.ready?'Billede '+(i+1):'Afventer billede '+(i+1))+'</div>';photos.append(el);});
 async function loadImages(){if(loading||!card.isConnected||!card.querySelector('.order-fold').open)return;loading=true;if(button){button.disabled=true;button.hidden=false;button.textContent='Henter billeder…';}let failed=false;for(let i=0;i<r.photos.length;i++){if(!card.isConnected||!card.querySelector('.order-fold').open)break;if(urls[i])continue;const p=r.photos[i],el=photos.children[i];try{const data=await rpc('image',{id:r.id,revision:r.revision,key:p.key});if(!card.isConnected)break;const mime=/^image\/(jpeg|png|webp|gif)$/.test(data.mime)?data.mime:'image/jpeg',url='data:'+mime+';base64,'+data.base64;urls[i]=url;const ext=mime.split('/')[1].replace('jpeg','jpg'),filename='Ordre-'+String(r.order).replace(/[^a-zA-Z0-9_-]/g,'_')+'-v'+r.revision+'-billede-'+(i+1)+'.'+ext;files[i]={name:filename,base64:data.base64};el.innerHTML='<label class="photo-select" '+(selecting?'':'hidden')+'><input type="checkbox" aria-label="Vælg billede '+(i+1)+'"><span>Vælg</span></label><button class="photo-open" aria-label="Åbn billede '+(i+1)+'"><img loading="lazy" alt="Billede '+(i+1)+'"></button><figcaption><span>Billede '+(i+1)+'</span><a class="photo-download">Download ↓</a></figcaption>';el.querySelector('img').src=url;const link=el.querySelector('a');link.href=url;link.download=filename;el.querySelector('.photo-open').onclick=()=>{const ready=urls.filter(Boolean);showPhoto(ready,ready.indexOf(url));};el.querySelector('input').onchange=e=>{if(e.target.checked)selected.add(i);else selected.delete(i);updateSelection();};}catch(e){failed=true;el.querySelector('.photo-placeholder').textContent=e.code==='PENDING'?'Afventer overførsel · prøv igen':'Kunne ikke hente billedet';}}loading=false;if(button){button.disabled=false;button.textContent='Prøv billeder igen';button.hidden=!failed;}}
 card.querySelector('.order-fold').addEventListener('toggle',e=>{if(e.target.open&&r.photos.length)enqueueImages(loadImages);});if(button)button.onclick=()=>enqueueImages(loadImages);
 const details=card.querySelector('.order-history');if(details)details.ontoggle=async()=>{if(!details.open||details.dataset.loaded)return;const h=details.querySelector('.history');h.textContent='Henter historik…';try{const history=await rpc('history',{id:r.id});h.replaceChildren(...history.filter(x=>x.revision!==r.revision).map(x=>orderCard(x,true)));details.dataset.loaded='yes';}catch(e){h.textContent=e.message;}};
 return card;
}
const imageTasks=[];let imageRunning=false;async function enqueueImages(fn){imageTasks.push(fn);if(imageRunning)return;imageRunning=true;try{while(imageTasks.length)await imageTasks.shift()();}finally{imageRunning=false;}}
window.addEventListener('online',()=>{if(state){state.jobs.forEach(j=>{if(j.code==='NETWORK'){j.error='';j.code='';}});pump();}});window.addEventListener('beforeunload',e=>{if(state&&(state.jobs.some(j=>j.status!=='done')||state.draft.photos.some(p=>!p.saved))){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)pump();});setInterval(()=>{if(!document.hidden)pump();},30000);
window.lagerPrepareUpdate=async()=>{
 if(window.PackingScan?.busy||window.lagerActivationBusy?.()||busy||saveBusy||$('#camera').open||state&&(state.jobs.some(j=>j.status!=='done')||state.draft.photos.some(p=>p.upload&&!p.saved)))return 'Vent med at opdatere, til billeder og registreringer er gemt. Luk også kameraet først.';
 updating=true;app.inert=true;queue.inert=true;
 try{if(state&&role==='warehouse')await persist();}catch(e){updating=false;app.inert=false;queue.inert=false;throw e;}
 return '';
};
